package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import androidx.datastore.preferences.core.edit
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class RecentSettingsToolUiTest:OrganizedSettingsFixture(){
 @Before fun reset(){runBlocking{ctx.ldStore.edit{it[K.recentSettingsTool]=false;it[K.lastSettingsTool]="";it[K.settingsToolSearch]=false;it[K.settingsSectionSearch]=false}};await{LdApp.settings.value.let{!it.recentSettingsTool&&it.lastSettingsTool.isEmpty()&&!it.settingsToolSearch&&!it.settingsSectionSearch}}}
 private fun enable(){runBlocking{ctx.ldStore.edit{it[K.recentSettingsTool]=true}};await{LdApp.settings.value.recentSettingsTool}}
 @Test fun defaultsOffAndOnlyKnownRoutes(){assertFalse(LdSettings().recentSettingsTool);assertEquals("",LdSettings().lastSettingsTool);for(t in ORGANIZED_TOOLS)assertEquals(t,recentSettingsTool(t.route));for(r in listOf("","tel:123","call:123","settingstools:live","callcanvas:123","CALLCANVAS"," callcanvas"))assertNull(recentSettingsTool(r))}
 @Test fun offDoesNotRecordOrShowShortcut(){start();val before=LdApp.settings.value;show("settingstools:notes");tapTag("settings_tool_callcanvas");assertEquals("callcanvas",opened.last());assertEquals(before,LdApp.settings.value);show("settingshub:tools");rule.onNodeWithTag("recent_settings_tool_open",true).assertDoesNotExist();rule.onNodeWithTag("recent_settings_tool_empty",true).assertDoesNotExist();assertNull(rule.activity.state.pendingCall)}
 @Test fun sectionOpenStoresOnlyRouteAndShortcutReturns(){start();enable();val before=LdApp.settings.value;show("settingstools:notes");tapTag("settings_tool_callcanvas");await{LdApp.settings.value.lastSettingsTool=="callcanvas"&&opened.lastOrNull()=="callcanvas"};assertEquals(before.copy(lastSettingsTool="callcanvas"),LdApp.settings.value);show("settingshub:tools");rule.onNodeWithTag("recent_settings_tool_open",true).assertExists();tapTag("recent_settings_tool_open");assertEquals("callcanvas",opened.last());assertNull(rule.activity.state.pendingCall)}
 @Test fun clearAndInvalidRouteSafeEmptyState(){start();enable();runBlocking{ctx.ldStore.edit{it[K.lastSettingsTool]="callcanvas:private-number"}};await{LdApp.settings.value.lastSettingsTool.contains(":")};show("settingshub:tools");rule.onNodeWithTag("recent_settings_tool_open",true).assertDoesNotExist();rule.onNodeWithTag("recent_settings_tool_empty",true).assertExists();tapTag("recent_settings_tool_clear");await{LdApp.settings.value.lastSettingsTool.isEmpty()};runBlocking{ctx.ldStore.edit{it[K.lastSettingsTool]="calltally"}};await{rule.onAllNodesWithTag("recent_settings_tool_open",true).fetchSemanticsNodes().size==1};val before=LdApp.settings.value;tapTag("recent_settings_tool_clear");await{LdApp.settings.value.lastSettingsTool.isEmpty()&&rule.onAllNodesWithTag("recent_settings_tool_empty",true).fetchSemanticsNodes().size==1};assertEquals(before.copy(lastSettingsTool=""),LdApp.settings.value)}
 @Test fun disableStopsRecordingAndReenableRetainsChosenShortcut(){start();enable();show("settingstools:live");tapTag("settings_tool_ivrmenus");await{LdApp.settings.value.lastSettingsTool=="ivrmenus"};show("settingshub:tools");val before=LdApp.settings.value;tapTag("recent_settings_tool_switch");await{!LdApp.settings.value.recentSettingsTool};assertEquals(before.copy(recentSettingsTool=false),LdApp.settings.value);show("settingstools:calculators");tapTag("settings_tool_calltally");assertEquals("ivrmenus",LdApp.settings.value.lastSettingsTool);show("settingshub:tools");rule.onNodeWithTag("recent_settings_tool_open",true).assertDoesNotExist();tapTag("recent_settings_tool_switch");await{LdApp.settings.value.recentSettingsTool&&rule.onAllNodesWithTag("recent_settings_tool_open",true).fetchSemanticsNodes().size==1};assertEquals(before,LdApp.settings.value)}
 @Test fun globalAndSectionSearchBothRecordControlsOnly(){start();enable();runBlocking{ctx.ldStore.edit{it[K.settingsToolSearch]=true;it[K.settingsSectionSearch]=true}};await{LdApp.settings.value.settingsToolSearch&&LdApp.settings.value.settingsSectionSearch};show("settingshub:tools");rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_tool_query")),true).performTextReplacement("IVR");settle();tapTag("settings_tool_result_ivrmenus");await{LdApp.settings.value.lastSettingsTool=="ivrmenus"};show("settingstools:notes");println("DIAG528 recent nanos=${System.nanoTime()} route=${route.value} sectionSearch=${LdApp.settings.value.settingsSectionSearch} toolSearch=${LdApp.settings.value.settingsToolSearch} converterFullUnits=${LdApp.settings.value.converterFullUnits}");try{rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_section_query")),true).performTextReplacement("canvas")}catch(f:Throwable){println("DIAG528 recent failure nanos=${System.nanoTime()}");runCatching{println(rule.onRoot(true).printToString());saveShot(rule,"DIAG528-recent-failure")}.onFailure{println("DIAG528 capture failed: $it")};throw f};settle();tapTag("settings_tool_callcanvas");await{LdApp.settings.value.lastSettingsTool=="callcanvas"};assertEquals("callcanvas",opened.last());assertNull(rule.activity.state.pendingCall)}
 @Test fun finderAndOtherCategoriesStayUnchanged(){start();enable();assertTrue(SettingsFinder.search("Recent call-tool shortcut").any{it.id=="recent-settings-tool"&&it.route=="settingshub:tools"});val before=LdApp.settings.value;show("settingshub:look");rule.onNodeWithTag("recent_settings_tool_empty",true).assertDoesNotExist();tapTag("settings_destination_recents");assertEquals(before,LdApp.settings.value);assertNull(rule.activity.state.pendingCall)}
 @Test fun dayAndOffPixels(){start();enable();show("settingstools:calculators");tapTag("settings_tool_installmentpreview");await{LdApp.settings.value.lastSettingsTool=="installmentpreview"};show("settingshub:tools");shot("SET515-day");tapTag("recent_settings_tool_clear");await{LdApp.settings.value.lastSettingsTool.isEmpty()};shot("SET515-empty");tapTag("recent_settings_tool_switch");await{!LdApp.settings.value.recentSettingsTool};show("settingshub:tools");shot("SET515-off");rule.mainClock.autoAdvance=true;rule.onNodeWithTag("recent_settings_tool_switch",true).performScrollTo();settle();shot("SET515-switch")}
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w320dp-h640dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class RecentSettingsToolNightUiTest:OrganizedSettingsFixture(){
 @Test fun nightLargeShortcut(){start(night=true);runBlocking{ctx.ldStore.edit{it[K.recentSettingsTool]=true;it[K.lastSettingsTool]="incomingstudio"}};await{LdApp.settings.value.recentSettingsTool&&LdApp.settings.value.lastSettingsTool=="incomingstudio"};show("settingshub:tools");shot("SET515-night");rule.onNodeWithText("Incoming card try-out and profiles",false,true).assertIsDisplayed();tapTag("recent_settings_tool_open");await{opened.lastOrNull()=="incomingstudio"};assertNull(rule.activity.state.pendingCall)}
}
